<script setup>
import { ref,onMounted,onBeforeUnmount } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { call } from '../api.js'
const emit=defineEmits(['error'])
const rows=ref([]),total=ref(0),page=ref(1),status=ref('all'),query=ref(''),busy=ref(false),saving=ref(false),selected=ref(null)
let generation=0
const labels={ACTIVE:'素材库',TRASHED:'回收站',PURGING:'永久清理中',PURGE_FAILED:'清理未完成',DELETED:'已永久清理',UNUSED:'未引用'}
const time=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—'
const bytes=v=>v>=1048576?(v/1048576).toFixed(2)+' MB':(v/1024).toFixed(1)+' KB'
async function load(){const ticket=++generation;busy.value=true;try{const r=await call('GET','/admin-api/v1/media?'+new URLSearchParams({page:String(page.value),size:'20',q:query.value,status:status.value}));if(ticket===generation){rows.value=r.items;total.value=r.total}}catch(e){if(ticket===generation)emit('error',e)}finally{if(ticket===generation)busy.value=false}}
async function act(row,action){let confirmation='';try{if(action==='purge'){const result=await ElMessageBox.prompt('永久删除不可恢复。输入完整素材路径确认：'+row.key,'永久清理素材',{type:'warning',inputValidator:v=>v===row.key||'路径不一致'});confirmation=result.value}else await ElMessageBox.confirm(action==='trash'?'移入回收站后从音频选项隐藏，7天内可恢复；已被引用的素材无法移入。':'恢复后重新出现在素材库，不会自动发布。',action==='trash'?'移入回收站':'恢复素材',{type:'warning'})}catch{return}saving.value=true;try{await call('POST','/admin-api/v1/media/actions',{key:row.key,expectedVersion:row.version,action,confirmation});ElMessage.success('素材状态已更新');await load()}catch(e){emit('error',e)}finally{saving.value=false}}
function search(){page.value=1;load()}
onMounted(load);onBeforeUnmount(()=>generation++)
</script>
<template><section class="surface" v-loading="busy"><div class="surface-heading"><h3>素材引用与回收站</h3><el-button @click="load">刷新引用</el-button></div><p class="muted">保护全部人物草稿与已发布素材包、全部音频历史版本及待执行审批。内置素材不可清理。库存覆盖已有目录可见素材及本功能接入后登记的上传，不扫描存储桶中的其他文件。</p><div class="section-toolbar"><el-input v-model="query" placeholder="搜索素材路径" aria-label="搜索素材路径" clearable style="max-width:320px" @keyup.enter="search" /><el-select v-model="status" aria-label="素材状态" style="width:160px" @change="search"><el-option label="全部状态" value="all" /><el-option v-for="(label,key) in labels" :key="key" :label="label" :value="key" /></el-select><el-button @click="search">查询</el-button></div><el-table :data="rows"><el-table-column label="素材" min-width="260"><template #default="{row}"><span class="ops-key">{{row.key}}</span><small>{{row.kind==='audio'?'音频':'人物图片'}} · {{bytes(row.bytes)}}</small></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag>{{labels[row.status]}}</el-tag></template></el-table-column><el-table-column label="引用" min-width="140"><template #default="{row}"><el-button v-if="row.references.length" text @click="selected=row">{{row.references.length}} 项引用</el-button><span v-else class="muted">当前未引用</span></template></el-table-column><el-table-column label="最早永久清理" min-width="180"><template #default="{row}">{{time(row.purgeAfter)}}</template></el-table-column><el-table-column label="操作" min-width="220"><template #default="{row}"><el-button v-if="row.status==='ACTIVE'" size="small" :disabled="saving||row.references.length>0" @click="act(row,'trash')">移入回收站</el-button><template v-if="['TRASHED','PURGING','PURGE_FAILED'].includes(row.status)"><el-button v-if="row.status==='TRASHED'" size="small" :disabled="saving" @click="act(row,'restore')">恢复</el-button><el-button size="small" type="danger" plain :disabled="saving||row.references.length>0||Date.now()<row.purgeAfter" @click="act(row,'purge')">{{row.status==='TRASHED'?'永久清理':'重试清理'}}</el-button></template></template></el-table-column></el-table><el-empty v-if="!rows.length&&!busy" description="没有符合条件的上传素材" :image-size="60" /><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next,total" @current-change="load" /></section><el-drawer :model-value="!!selected" title="素材引用详情" size="min(520px,95vw)" @close="selected=null"><template v-if="selected"><p class="ops-key">{{selected.key}}</p><ul><li v-for="ref in selected.references" :key="ref">{{ref}}</li></ul><p class="muted">历史人物包保留，确保进行中的房间及旧版本资源仍可访问。</p></template></el-drawer></template>
